import {copyHTML,copyRaw} from './site-copy.js';
import {backend} from './backend.js';
import {escape as e} from './store.js';
let recoveryError='';
export function forgotPage(){return `<section class="card auth-card"><span class="eyebrow">${copyHTML("recovery.a93ab127131b")}</span><h2>${copyHTML("recovery.afd25fdf17c7")}</h2><p class="muted">${copyHTML("recovery.6819729e5a21")}</p><form id="forgot-form"><label for="recovery-email">${copyHTML("recovery.969ccbd3cf63")}</label><input id="recovery-email" name="email" type="email" autocomplete="email" required><p id="recovery-status" class="muted" role="status"></p><div class="actions"><button class="btn primary">${copyHTML("recovery.708c5d67ba8e")}</button><button class="btn" type="button" data-route="login">${copyHTML("recovery.3e3806ff1730")}</button></div></form></section>`;}
export function resetPage(){return `<section class="card auth-card"><span class="eyebrow">${copyHTML("recovery.a93ab127131b")}</span><h2>${copyHTML("recovery.833b8512168f")}</h2>${backend.recoveryReady()?`<form id="reset-form"><label for="new-password">${copyHTML("recovery.3dd9df4441fb")}</label><div class="password-field"><input id="new-password" name="password" type="password" minlength="8" maxlength="200" autocomplete="new-password" required><button type="button" class="btn password-toggle" data-password-toggle="new-password" data-password-label="new password" aria-controls="new-password" aria-label="${copyHTML("recovery.328515984aec")}" aria-pressed="false">${copyHTML("recovery.0df6f1cad36c")}</button></div><label for="confirm-password">${copyHTML("recovery.5ac265f396a2")}</label><div class="password-field"><input id="confirm-password" name="confirm" type="password" minlength="8" maxlength="200" autocomplete="new-password" required><button type="button" class="btn password-toggle" data-password-toggle="confirm-password" data-password-label="confirmation password" aria-controls="confirm-password" aria-label="${copyHTML("recovery.d8144e9395f8")}" aria-pressed="false">${copyHTML("recovery.0df6f1cad36c")}</button></div><p id="reset-status" class="muted" role="status"></p><button type="submit" id="reset-submit" class="btn primary">${copyHTML("recovery.fe45b4014135")}</button></form>`:`<p class="muted">${e(recoveryError||'Open the password-reset link sent to your email to set a new password.')}</p><button class="btn primary" data-route="forgot">${copyHTML("recovery.654c78905b96")}</button>`}</section>`;}
export async function handleRecoveryLink(){const params=new URLSearchParams(location.hash.slice(1));if(params.get('type')!=='recovery')return false;const access=params.get('access_token'),refresh=params.get('refresh_token');history.replaceState(null,'',location.pathname+location.search+'#reset');try{if(!access||!refresh)throw new Error(copyRaw("recovery.6ea969c2fe98"));await backend.acceptRecovery(access,refresh,Number(params.get('expires_in'))||3600);}catch(err){recoveryError=err.message;}return true;}
export function bindRecovery(ui){const forgot=document.querySelector('#forgot-form');if(forgot)forgot.onsubmit=async event=>{event.preventDefault();const button=forgot.querySelector('button'),status=document.querySelector('#recovery-status');button.disabled=true;try{await backend.requestRecovery(new FormData(forgot).get('email').trim(),location.origin+location.pathname+'#reset');status.textContent=copyRaw("recovery.882f46e6ac01");}catch(err){status.textContent=err.message;}finally{button.disabled=false;}};const reset=document.querySelector('#reset-form');if(reset)reset.onsubmit=async event=>{event.preventDefault();const form=new FormData(reset),status=document.querySelector('#reset-status'),button=reset.querySelector('#reset-submit');if(form.get('password')!==form.get('confirm')){status.textContent=copyRaw("recovery.f694aaa8da2c");return;}button.disabled=true;try{await backend.resetPassword(form.get('password'));location.hash='login';ui.toast(copyRaw("recovery.692fa3c3b985"));}catch(err){status.textContent=err.message;}finally{button.disabled=false;}};}
